import json, sys, hashlib
sys.path.insert(0, 'source')
from ledger import summarize
for token in ['1', '1.0', '1e0', 'true', 'null', '-0']:
 row = json.loads('{\"key\":\"x\",\"amount\":\"1\",\"priority\":'+token+'}')
 try: print(token, summarize([row]))
 except Exception as e: print(token, type(e).__name__, str(e))
for name in ['source/ledger.py', 'source/test_ledger.py']:
 print(name, hashlib.sha256(open(name, 'rb').read()).hexdigest())
